#!/usr/bin/env bash
# Wrap a macOS binary in a double-clickable .app bundle.
# usage: make-app-bundle.sh <binary> <output.app> <version>
set -euo pipefail

BIN="${1:?binary path required}"
APP="${2:?output .app path required}"
VERSION="${3:-1.0.0}"

rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"

cp "$BIN" "$APP/Contents/MacOS/SuperDario"
chmod +x "$APP/Contents/MacOS/SuperDario"

# The icon bundle is generated by `go run ./cmd/genicon`.
ICNS="$(dirname "$0")/../assets/icon.icns"
ICON_KEY=""
if [ -f "$ICNS" ]; then
	cp "$ICNS" "$APP/Contents/Resources/icon.icns"
	ICON_KEY='	<key>CFBundleIconFile</key>              <string>icon</string>'
else
	echo "note: assets/icon.icns missing — run 'go run ./cmd/genicon' for the app icon" >&2
fi

cat > "$APP/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>CFBundleName</key>                  <string>Super Dario</string>
	<key>CFBundleDisplayName</key>           <string>Super Dario</string>
	<key>CFBundleExecutable</key>            <string>SuperDario</string>
${ICON_KEY}
	<key>CFBundleIdentifier</key>            <string>com.superdario.game</string>
	<key>CFBundleVersion</key>               <string>${VERSION}</string>
	<key>CFBundleShortVersionString</key>    <string>${VERSION}</string>
	<key>CFBundlePackageType</key>           <string>APPL</string>
	<key>LSMinimumSystemVersion</key>        <string>10.15</string>
	<key>NSHighResolutionCapable</key>       <true/>
	<key>NSSupportsAutomaticGraphicsSwitching</key> <true/>
	<key>LSApplicationCategoryType</key>     <string>public.app-category.arcade-games</string>
</dict>
</plist>
PLIST

echo "bundled: $APP"
